const { Client } = require('pg');
const http = require('http');

const PG      = { host:'172.18.0.4', port:5432, database:'data_warehouse_gold', user:'nyanu', password:'nyanu', connectionTimeoutMillis:10000 };
const PROXY   = '172.18.0.8';
const PORT    = 3128;
const BASE    = '/BC260/api/etlpipeline/warehouse/v1.0';
const COMPANY = $vars.BC_COMPANY_ID || '00000000-0000-0000-0000-000000000000';
const ENTITY  = 'etlDistances';
const NOW     = new Date().toISOString();

function bcReq(method, path, body) {
  return new Promise((resolve, reject) => {
    const pl = body ? JSON.stringify(body) : null;
    const req = http.request({
      hostname: PROXY, port: PORT,
      path: `${BASE}/companies(${COMPANY})/${path}`,
      method,
      headers: {
        'Content-Type': 'application/json', 'Accept': 'application/json',
        ...(pl ? { 'Content-Length': Buffer.byteLength(pl) } : {}),
        ...(method === 'PATCH' ? { 'If-Match': '*' } : {})
      }
    }, res => { let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve({status:res.statusCode,body:d})); });
    req.on('error', reject);
    if (pl) req.write(pl);
    req.end();
  });
}

async function upsert(keyVal, data) {
  const r = await bcReq('POST', ENTITY, data);
  if (r.status === 201 || r.status === 200) return { action:'inserted', key:keyVal, status:r.status };
  if (r.status === 409 || r.status === 422) {
    const r2 = await bcReq('PATCH', `${ENTITY}('${encodeURIComponent(keyVal)}')`, data);
    return { action:'updated', key:keyVal, status:r2.status };
  }
  return { action:'error', key:keyVal, status:r.status, detail:r.body.substring(0,200) };
}

const client = new Client(PG);
await client.connect();
const res = await client.query(`
  SELECT session_id, session_date,
         total_distance_km, total_distance_meters,
         max_speed_kmh, avg_speed_kmh,
         total_active_seconds, event_count,
         first_event_at, last_event_at
  FROM dim_distances
`);
await client.end();

const results = [];
for (const row of res.rows) {
  const r = await upsert(row.session_id, {
    sessionId: row.session_id||'',
    sessionDate: row.session_date ? new Date(row.session_date).toISOString().split('T')[0] : '',
    totalDistanceKm: parseFloat(row.total_distance_km)||0,
    totalDistanceMeters: parseFloat(row.total_distance_meters)||0,
    maxSpeedKmh: parseFloat(row.max_speed_kmh)||0,
    avgSpeedKmh: parseFloat(row.avg_speed_kmh)||0,
    totalActiveSeconds: parseInt(row.total_active_seconds)||0,
    eventCount: parseInt(row.event_count)||0,
    firstEventAt: row.first_event_at ? new Date(row.first_event_at).toISOString() : '',
    lastEventAt: row.last_event_at  ? new Date(row.last_event_at).toISOString()  : '',
    etlLoadedAt: NOW
  });
  results.push(r);
}
const inserted = results.filter(r=>r.action==='inserted').length;
const updated  = results.filter(r=>r.action==='updated').length;
const errors   = results.filter(r=>r.action==='error').length;
console.log(`[WF-08D] dim_distances → BC: ${inserted} inserts | ${updated} updates | ${errors} errors`);
return [{ json: { table:'dim_distances', total:results.length, inserted, updated, errors } }];
